            Instant returnedAt,
            String keeperId) {
    }

    /** 挂接/拆除双人确认证据视图（只追加，不可覆盖）。 */
    public record EvidenceView(
            long evidenceId,
            String wireCode,
            long ticketId,
            int stepSeq,
            String action,
            String operatorId,
            String guardianId,
            Instant occurredAt,
            Instant createdAt) {
    }

    /** 实物明细：台账状态、借用历史与操作证据。 */
    public record WireDetailView(
            WireView wire,
            List<LoanView> loans,
            List<EvidenceView> evidences) {
    }

    /** 批量借用/归还结果：成功后所有实物一致的新版本号。 */
    public record WireBatchResult(
            String action,
            int version,
            List<String> wireCodes,
            Instant occurredAt) {
    }

    /** 挂接/拆除结果。 */
    public record WireStepResult(
            String action,
            String wireCode,
            int stepSeq,
            String wireStatus,
            int version,
            Instant occurredAt) {
    }
}

