    @Test
    void idempotentSameKeyDifferentParamsConflict() throws Exception {
        long ticket = draftTicket("idemx", "INT-1101", new StepSpec("OPEN_BREAKER", "BR-1101", "OPEN"));
        String body1 = mapper.writeValueAsString(Map.of(
                "requestId", "idem-x",
